#Salomone_Rossi_Corrente-RF.rb
#These 7 Corrente were written in 1613
#I have transcribed them from a MuseScore by w8erw to play on Sonic Pi.
#quite a lot of fun debugging this, especially the harpsichord part!
#program designed to send haprsichord voices to vmpk va midi and reimport live_audio
#you can also set midiplay to false and play this part with internal piano synth instead

st=0 #start section number for debug purposes normally leave at 0
midiplay = true #set to false for internal piano synth
#if using midi adjust port as necesssary
use_midi_defaults port: "iac_driver_sonic-pi"#iac driver sonicpi"
 #for harpsichord or false for piano substitute
use_debug true
use_midi_logging true
define :mplay do |notes,durs,channel,tr,vel=100| #send list of midi notes/durations
  for x in 0..notes.length-1
    if notes[x].respond_to?(:each)
      notes[x].each do |n|
        midi note(n)+tr,sustain: durs[x],channel: channel,velocity: vel
      end
    else
      midi note(notes[x])+tr,sustain: durs[x],channel: channel,velocity: vel
    end
    sleep durs[x]
  end
end
#two debugging functions for checking parts
define :check do |durs| #check total duration of a given part
  total=0
  durs.each do |x|
    total += x
  end
  return total
end

define :cklen do |n,d| #check number of entries in a given note/duration pair of lists
puts n.length,d.length
end
