  live_audio :vmpk,:stop #clear any existing audio input
  sleep 1
  5.times do |i|
    midi_pc 6,channel: i+1 #set chans 1-3 to harpsichord (pc 6)
  end
  sleep 1 #allow initialisation to complete
  
  in_thread do
    for i in st..a4.length-1
      use_bpm c4[i]
      mplay a4[i],b4[i],1,0,80
    end
  end
  
  in_thread do
    for i in st..a5.length-1
      use_bpm c5[i]
      mplay a5[i],b5[i],2,0,80
    end
  end
  
  in_thread do
    for i in st..a6.length-1
      use_bpm c6[i]
      mplay a6[i],b6[i],3,0,80
    end
  end
  
  in_thread do
    for i in st..a7.length-1
      use_bpm c7[i]
      mplay a7[i],b7[i],4,0,80
    end
  end
  
    in_thread do
